    if ob.type in ('MESH','LIGHT'):
        ob.location.x *= K; ob.location.z *= K
bpy.data.objects['LH_lit_lamp'].data.energy = 3000
bpy.data.objects['LH_lit_lamp'].location.z = 9.0*K
