mn=[1e9]*3; mx=[-1e9]*3
for ob in bpy.data.objects:
    if ob.type=='MESH' and ob.name.startswith('LH_lit'):
        for v in ob.data.vertices:
            w=ob.matrix_world@v.co
            for i in range(3): mn[i]=min(mn[i],w[i]); mx[i]=max(mx[i],w[i])
print('lit bbox', [round(x,2) for x in mn],[round(x,2) for x in mx],'height',round(mx[2]-mn[2],3))
